#################################################################

:hasGLN rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasAddress rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:containsMessage rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasLIN rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasUNS rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasCNT rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasInvoiceNumber rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasInvoiceAmount rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasNetPrice rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasQuantity rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasBusinessProcess rdf:type owl:ObjectProperty ; owl:FunctionalProperty .

#################################################################
# Disjointness
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:DetailSection owl:disjointWith :SummarySection .
:SummarySection owl:disjointWith :HeaderSection .
:Organization owl:disjointWith :Address .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

