  owl:FunctionalProperty .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:label "has segment" ;
  rdfs:comment "Message includes segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment .

:hasSection rdf:type owl:ObjectProperty ;
  rdfs:label "has section" ;
  rdfs:comment "Message includes header, detail, and summary sections." ;
  rdfs:domain :Message ;
  rdfs:range :HeaderSection, :DetailSection, :SummarySection .

:hasLineItem rdf:type owl:ObjectProperty ;
  rdfs:label "has line item" ;
  rdfs:comment "Detail section includes line items." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem .

:hasLIN rdf:type owl:ObjectProperty ;
  rdfs:label "has LIN segment" ;
  rdfs:comment "Line item is anchored by a LIN segment." ;
  rdfs:domain :LineItem ;
  rdfs:range :LIN_Segment ;
  owl:FunctionalProperty .

:hasPIA rdf:type owl:ObjectProperty ;
  rdfs:label "has PIA segment" ;
  rdfs:comment "Line item has additional product identification." ;
  rdfs:domain :LineItem ;
  rdfs:range :PIA_Segment .

:hasPAC rdf:type owl:ObjectProperty ;
  rdfs:label "has PAC segment" ;
  rdfs:comment "Line item has packaging details." ;
  rdfs:domain :LineItem ;
  rdfs:range :PAC_Segment .

:hasLOC rdf:type owl:ObjectProperty ;
  rdfs:label "has LOC segment" ;
  rdfs:comment "Line item has location details." ;
  rdfs:domain :LineItem ;
  rdfs:range :LOC_Segment .

:hasDOC rdf:type owl:ObjectProperty ;
  rdfs:label "has DOC segment" ;
  rdfs:comment "Header section includes document/message details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :DOC_Segment .

:hasUNS rdf:type owl:ObjectProperty ;
  rdfs:label "has UNS segment" ;
  rdfs:comment "Summary section includes UNS segment for section control." ;
  rdfs:domain :SummarySection ;
  rdfs:range :UNS_Segment ;
  owl:FunctionalProperty .

:hasCNT rdf:type owl:ObjectProperty ;
  rdfs:label "has CNT segment" ;
  rdfs:comment "Summary section includes CNT segment for control totals." ;
  rdfs:domain :SummarySection ;
  rdfs:range :CNT_Segment ;
  owl:FunctionalProperty .

:hasItem rdf:type owl:ObjectProperty ;
  rdfs:label "has item" ;
  rdfs:comment "Line item references the sold item." ;
  rdfs:domain :LineItem ;
  rdfs:range :Item .

:hasNetPrice rdf:type owl:DatatypeProperty ;
  rdfs:label "has net price" ;
  rdfs:comment "Net price for a line item." ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:decimal ;
  owl:FunctionalProperty .

:hasQuantity rdf:type owl:DatatypeProperty ;
  rdfs:label "has quantity" ;
  rdfs:comment "Quantity for a line item." ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:integer ;
  owl:FunctionalProperty .

:hasInvoiceAmount rdf:type owl:DatatypeProperty ;
  rdfs:label "has invoice amount" ;
  rdfs:comment "Invoice total amount." ;
  rdfs:domain :SummarySection ;
  rdfs:range xsd:decimal ;
  owl:FunctionalProperty .

:hasInvoiceNumber rdf:type owl:DatatypeProperty ;
  rdfs:label "has invoice number" ;
  rdfs:comment "Invoice unique number." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string ;
  owl:FunctionalProperty .

:hasTax rdf:type owl:DatatypeProperty ;
  rdfs:label "has tax" ;
  rdfs:comment "Tax amount for summary section." ;
  rdfs:domain :SummarySection ;
  rdfs:range xsd:decimal ;
  owl:FunctionalProperty .

:hasReferenceNumber rdf:type owl:DatatypeProperty ;
  rdfs:label "has reference number" ;
  rdfs:comment "Reference number in header section." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string ;
  owl:FunctionalProperty .

:hasDate rdf:type owl:ObjectProperty ;
  rdfs:label "has date segment" ;
  rdfs:comment "Header section includes date/time/period segment." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :DTM_Segment .

:hasOrganization rdf:type owl:ObjectProperty ;
  rdfs:label "has organization" ;
  rdfs:comment "Invoice includes participating organizations." ;
  rdfs:domain :Invoice ;
  rdfs:range :Organization .

:hasAgentRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:label "has agent role assignment" ;
  rdfs:comment "Organization has assigned roles for invoice context." ;
  rdfs:domain :Organization ;
  rdfs:range :OrganizationRoleAssignment .

:playsRole rdf:type owl:ObjectProperty ;
  rdfs:label "plays role" ;
  rdfs:comment "Organization role assignment links to a role." ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :AgentRole .

:hasAddress rdf:type owl:ObjectProperty ;
  rdfs:label "has address" ;
  rdfs:comment "Organization has a specific address." ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  owl:FunctionalProperty .

:hasGLN rdf:type owl:DatatypeProperty ;
  rdfs:label "has GLN" ;
  rdfs:comment "Organization's global location number." ;
  rdfs:domain :Organization ;
  rdfs:range xsd:string ;
  owl:FunctionalProperty .

:hasBusinessProcess rdf:type owl:ObjectProperty ;
  rdfs:label "has business process" ;
  rdfs:comment "Invoice is assigned to a business process." ;
  rdfs:domain :Invoice ;
  rdfs:range :BusinessProcess ;
  owl:FunctionalProperty .

:hasMonetaryAmount rdf:type owl:ObjectProperty ;
  rdfs:label "has monetary amount segment" ;
  rdfs:comment "Summary section has monetary breakdowns." ;
  rdfs:domain :SummarySection ;
  rdfs:range :MOA_Segment .

:hasLineMonetaryAmount rdf:type owl:ObjectProperty ;
  rdfs:label "has line monetary amount segment" ;
  rdfs:comment "Line item has monetary breakdowns." ;
  rdfs:domain :LineItem ;
  rdfs:range :MOA_Segment .

:hasReference rdf:type owl:ObjectProperty ;
  rdfs:label "has reference segment" ;
  rdfs:comment "Header section references related documents." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :RFF_Segment .

:hasTaxDetail rdf:type owl:ObjectProperty ;
  rdfs:label "has tax segment" ;
  rdfs:comment "Summary section has tax details." ;
  rdfs:domain :SummarySection ;
  rdfs:range :TAX_Segment .

:hasLineTaxDetail rdf:type owl:ObjectProperty ;
  rdfs:label "has line tax segment" ;
  rdfs:comment "Line item has tax details." ;
  rdfs:domain :LineItem ;
  rdfs:range :TAX_Segment .

:hasMeasurement rdf:type owl:ObjectProperty ;
  rdfs:label "has measurement segment" ;
  rdfs:comment "Line item has measurement details." ;
  rdfs:domain :LineItem ;
  rdfs:range :MEA_Segment .

:hasQuantityDetail rdf:type owl:ObjectProperty ;
  rdfs:label "has quantity segment" ;
  rdfs:comment "Line item has quantity details." ;
  rdfs:domain :LineItem ;
  rdfs:range :QTY_Segment .

:hasAllowanceOrCharge rdf:type owl:ObjectProperty ;
  rdfs:label "has allowance/charge segment" ;
  rdfs:comment "Summary section has allowance/charge details." ;
  rdfs:domain :SummarySection ;
  rdfs:range :ALC_Segment .

:hasHeaderAllowanceOrCharge rdf:type owl:ObjectProperty ;
  rdfs:label "has header allowance/charge group" ;
  rdfs:comment "Header section has allowance/charge group (SG8)." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :SG8_AllowanceChargeGroup .

:hasHeaderTax rdf:type owl:ObjectProperty ;
  rdfs:label "has header tax group" ;
  rdfs:comment "Header section has tax group (SG6)." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :SG6_TaxGroup .

:hasReferenceGroup rdf:type owl:ObjectProperty ;
  rdfs:label "has reference group" ;
  rdfs:comment "Header section has reference group (SG2)." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :SG2_ReferenceGroup .

:hasCurrency rdf:type owl:ObjectProperty ;
  rdfs:label "has currency segment" ;
  rdfs:comment "Header section has currency details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :CUX_Segment .

:hasPriceDetail rdf:type owl:ObjectProperty ;
  rdfs:label "has price segment" ;
  rdfs:comment "Line item has price details." ;
  rdfs:domain :LineItem ;
  rdfs:range :PRI_Segment .

:hasItemDescription rdf:type owl:ObjectProperty ;
  rdfs:label "has item description segment" ;
  rdfs:comment "Line item has item description details." ;
  rdfs:domain :LineItem ;
  rdfs:range :IMD_Segment .

:hasContact rdf:type owl:ObjectProperty ;
  rdfs:label "has contact segment" ;
  rdfs:comment "Header section has contact details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :CTA_Segment .

:hasCommunication rdf:type owl:ObjectProperty ;
  rdfs:label "has communication segment" ;
  rdfs:comment "Contact segment has communication details." ;
  rdfs:domain :CTA_Segment ;
  rdfs:range :COM_Segment .

:hasTransport rdf:type owl:ObjectProperty ;
  rdfs:label "has transport segment" ;
  rdfs:comment "Header section has transport details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :TDT_Segment .

:hasTermsOfDelivery rdf:type owl:ObjectProperty ;
  rdfs:label "has terms of delivery segment" ;
  rdfs:comment "Header section has terms of delivery details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :TOD_Segment .

#################################################################
# Advanced Axioms & Restrictions
#################################################################

:LineItem rdf:type owl:Class ;
  owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :hasLIN ; owl:allValuesFrom :LIN_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:allValuesFrom xsd:decimal ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom xsd:integer ] .

:OrganizationRoleAssignment rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ] .

:Invoice rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasOrganization ; owl:someValuesFrom :Organization ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasBusinessProcess ; owl:allValuesFrom :BusinessProcess ] .

:HeaderSection rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasDate ; owl:someValuesFrom :DTM_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasReferenceGroup ; owl:someValuesFrom :SG2_ReferenceGroup ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasHeaderTax ; owl:someValuesFrom :SG6_TaxGroup ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasHeaderAllowanceOrCharge ; owl:someValuesFrom :SG8_AllowanceChargeGroup ] .

:SummarySection rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasUNS ; owl:allValuesFrom :UNS_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasCNT ; owl:allValuesFrom :CNT_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasMonetaryAmount ; owl:someValuesFrom :MOA_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasTaxDetail ; owl:someValuesFrom :TAX_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasAllowanceOrCharge ; owl:someValuesFrom :ALC_Segment ] .

#################################################################
# Property Characteristics
#################################################################

:hasGLN rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasAddress rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:containsMessage rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasLIN rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasUNS rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasCNT rdf:type owl:ObjectProperty ; owl:FunctionalProperty .
:hasInvoiceNumber rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasInvoiceAmount rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasNetPrice rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasQuantity rdf:type owl:DatatypeProperty ; owl:FunctionalProperty .
:hasBusinessProcess rdf:type owl:ObjectProperty ; owl:FunctionalProperty .

#################################################################
# Disjointness
#################################################################

:HeaderSection owl:disjointWith :DetailSection .
:DetailSection owl:disjointWith :SummarySection .
:SummarySection owl:disjointWith :HeaderSection .
:Organization owl:disjointWith :Address .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

#################################################################
# Annotations (rdfs:label, rdfs:comment for all classes/properties)
#################################################################
# (Already included above for all classes and properties)
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_StoryOntology rdf:type owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Ontology for E/D/E Industrial Procurement" ;
  rdfs:comment "A deep and profoundly structured OWL ontology representing the full EDIFACT D96A INVOIC message, including all mandatory segments, segment groups, business roles, and procurement context for semantic interoperability." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "EDIFACT envelope containing one or more messages." .

:Message rdf:type owl:Class ;
  rdfs:label "EDIFACT Message" ;
  rdfs:comment "A business document within an interchange envelope, e.g., INVOIC." .

:Invoice rdf:type owl:Class ;
  rdfs:label "Invoice" ;
  rdfs:comment "A commercial invoice message, compliant with EN 16931-1 and P2P-O." .

:Segment rdf:type owl:Class ;
  rdfs:label "EDIFACT Segment" ;
  rdfs:comment "Atomic structural unit in EDIFACT messages, e.g., BGM, NAD, LIN." .

:BGM_Segment rdf:type owl:Class ;
  rdfs:label "Beginning of Message Segment (BGM)" ;
  rdfs:comment "Identifies the type and number of the message." ;
  rdfs:subClassOf :Segment .

:NAD_Segment rdf:type owl:Class ;
  rdfs:label "Name and Address Segment (NAD)" ;
  rdfs:comment "Details of organizations and their roles in the transaction." ;
  rdfs:subClassOf :Segment .

:DTM_Segment rdf:type owl:Class ;
  rdfs:label "Date/Time/Period Segment (DTM)" ;
  rdfs:comment "Captures dates/times with EDIFACT qualifiers." ;
  rdfs:subClassOf :Segment .

:MOA_Segment rdf:type owl:Class ;
  rdfs:label "Monetary Amount Segment (MOA)" ;
  rdfs:comment "Monetary breakdowns, totals, and amounts." ;
  rdfs:subClassOf :Segment .

:RFF_Segment rdf:type owl:Class ;
  rdfs:label "Reference Segment (RFF)" ;
  rdfs:comment "References to related documents, e.g., PO, Delivery Note." ;
  rdfs:subClassOf :Segment .

:TAX_Segment rdf:type owl:Class ;
  rdfs:label "Tax Segment (TAX)" ;
  rdfs:comment "Tax details, rates, and types." ;
  rdfs:subClassOf :Segment .

:MEA_Segment rdf:type owl:Class ;
  rdfs:label "Measurement Segment (MEA)" ;
  rdfs:comment "Measurements relevant to items or logistics." ;
  rdfs:subClassOf :Segment .

:QTY_Segment rdf:type owl:Class ;
  rdfs:label "Quantity Segment (QTY)" ;
  rdfs:comment "Quantities for items or totals." ;
  rdfs:subClassOf :Segment .

:ALC_Segment rdf:type owl:Class ;
  rdfs:label "Allowance/Charge Segment (ALC)" ;
  rdfs:comment "Details of allowances and charges." ;
  rdfs:subClassOf :Segment .

:CUX_Segment rdf:type owl:Class ;
  rdfs:label "Currency Segment (CUX)" ;
  rdfs:comment "Currency details for the invoice." ;
  rdfs:subClassOf :Segment .

:PRI_Segment rdf:type owl:Class ;
  rdfs:label "Price Segment (PRI)" ;
  rdfs:comment "Price details for line items." ;
  rdfs:subClassOf :Segment .

:IMD_Segment rdf:type owl:Class ;
  rdfs:label "Item Description Segment (IMD)" ;
  rdfs:comment "Describes items in detail." ;
  rdfs:subClassOf :Segment .

:LIN_Segment rdf:type owl:Class ;
  rdfs:label "Line Item Number Segment (LIN)" ;
  rdfs:comment "Anchor for line item hierarchy and numbering." ;
  rdfs:subClassOf :Segment .

:PIA_Segment rdf:type owl:Class ;
  rdfs:label "Additional Product Identification Segment (PIA)" ;
  rdfs:comment "Additional identifiers for products." ;
  rdfs:subClassOf :Segment .

:PAC_Segment rdf:type owl:Class ;
  rdfs:label "Packaging Segment (PAC)" ;
  rdfs:comment "Packaging details for items." ;
  rdfs:subClassOf :Segment .

:LOC_Segment rdf:type owl:Class ;
  rdfs:label "Location Segment (LOC)" ;
  rdfs:comment "Location details for delivery, warehouse, etc." ;
  rdfs:subClassOf :Segment .

:DOC_Segment rdf:type owl:Class ;
  rdfs:label "Document/Message Details Segment (DOC)" ;
  rdfs:comment "Document or message references and context." ;
  rdfs:subClassOf :Segment .

:UNS_Segment rdf:type owl:Class ;
  rdfs:label "Section Control Segment (UNS)" ;
  rdfs:comment "Marks transition from detail to summary section." ;
  rdfs:subClassOf :Segment .

:CNT_Segment rdf:type owl:Class ;
  rdfs:label "Control Total Segment (CNT)" ;
  rdfs:comment "Totals for control and validation." ;
  rdfs:subClassOf :Segment .

:CTA_Segment rdf:type owl:Class ;
  rdfs:label "Contact Segment (CTA)" ;
  rdfs:comment "Contact details for organizations." ;
  rdfs:subClassOf :Segment .

:COM_Segment rdf:type owl:Class ;
  rdfs:label "Communication Segment (COM)" ;
  rdfs:comment "Communication details (phone, email, etc.)." ;
  rdfs:subClassOf :Segment .

:TDT_Segment rdf:type owl:Class ;
  rdfs:label "Transport Segment (TDT)" ;
  rdfs:comment "Transport details for delivery." ;
  rdfs:subClassOf :Segment .

:TOD_Segment rdf:type owl:Class ;
  rdfs:label "Terms of Delivery Segment (TOD)" ;
  rdfs:comment "Terms and conditions for delivery." ;
  rdfs:subClassOf :Segment .

:SG2_ReferenceGroup rdf:type owl:Class ;
  rdfs:label "Segment Group 2: Reference Group (RFF+DTM)" ;
  rdfs:comment "Repeating group for document references and dates." ;
  rdfs:subClassOf :CompositeDataElement .

:SG6_TaxGroup rdf:type owl:Class ;
  rdfs:label "Segment Group 6: Tax Group (TAX+MOA)" ;
  rdfs:comment "Repeating group for header tax and monetary details." ;
  rdfs:subClassOf :CompositeDataElement .

:SG8_AllowanceChargeGroup rdf:type owl:Class ;
  rdfs:label "Segment Group 8: Allowance/Charge Group (ALC+MOA)" ;
  rdfs:comment "Repeating group for header allowances/charges." ;
  rdfs:subClassOf :CompositeDataElement .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite element grouping multiple simple elements." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A single atomic value in a segment." .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A company or party involved in the invoice." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "Role played by an organization in the invoice." .

:Buyer rdf:type owl:Class ;
  rdfs:label "Buyer" ;
  rdfs:comment "The organization acting as buyer." ;
  rdfs:subClassOf :AgentRole .

:Supplier rdf:type owl:Class ;
  rdfs:label "Supplier" ;
  rdfs:comment "The organization acting as supplier." ;
  rdfs:subClassOf :AgentRole .

:DeliveryParty rdf:type owl:Class ;
  rdfs:label "Delivery Party" ;
  rdfs:comment "The organization acting as delivery party." ;
  rdfs:subClassOf :AgentRole .

:OrganizationRoleAssignment rdf:type owl:Class ;
  rdfs:label "Organization Role Assignment" ;
  rdfs:comment "Reified relation linking an organization to its role for a given invoice." ;
  rdfs:subClassOf :AgentRole .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address (headquarters, warehouse, etc.) for organizations." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "Identifier for organization locations." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice message." ;
  rdfs:subClassOf :Message .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." ;
  rdfs:subClassOf :Message .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals, taxes, and summary data." ;
  rdfs:subClassOf :Message .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A single invoice line, anchored by LIN_Segment." ;
  rdfs:subClassOf :DetailSection .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "Product or service sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price details for an item." .

:Quantity rdf:type owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "Quantity of item sold." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax applicable to the invoice or line item." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for invoice, PO, etc." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process context for the invoice." .

:InvoiceAmount rdf:type owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "Total amount for the invoice." .

:InvoiceNumber rdf:type owl:Class ;
  rdfs:label "Invoice Number" ;
  rdfs:comment "Unique identifier for the invoice." .

#################################################################
# Properties
#################################################################

:containsMessage rdf:type owl:ObjectProperty ;
  rdfs:label "contains message" ;
  rdfs:comment "Envelope contains one or more messages." ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  owl:FunctionalProperty .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:label "has segment" ;
  rdfs:comment "Message includes segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment .

:hasSection rdf:type owl:ObjectProperty ;
  rdfs:label "has section" ;
  rdfs:comment "Message includes header, detail, and summary sections." ;
  rdfs:domain :Message ;
  rdfs:range :HeaderSection, :DetailSection, :SummarySection .

:hasLineItem rdf:type owl:ObjectProperty ;
  rdfs:label "has line item" ;
  rdfs:comment "Detail section includes line items." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem .

:hasLIN rdf:type owl:ObjectProperty ;
  rdfs:label "has LIN segment" ;
  rdfs:comment "Line item is anchored by a LIN segment." ;
  rdfs:domain :LineItem ;
  rdfs:range :LIN_Segment ;
  owl:FunctionalProperty .

:hasPIA rdf:type owl:ObjectProperty ;
  rdfs:label "has PIA segment" ;
  rdfs:comment "Line item has additional product identification." ;
  rdfs:domain :LineItem ;
  rdfs:range :PIA_Segment .

:hasPAC rdf:type owl:ObjectProperty ;
  rdfs:label "has PAC segment" ;
  rdfs:comment "Line item has packaging details." ;
  rdfs:domain :LineItem ;
  rdfs:range :PAC_Segment .

:hasLOC rdf:type owl:ObjectProperty ;
  rdfs:label "has LOC segment" ;
  rdfs:comment "Line item has location details." ;
  rdfs:domain :LineItem ;
  rdfs:range :LOC_Segment .

:hasDOC rdf:type owl:ObjectProperty ;
  rdfs:label "has DOC segment" ;
  rdfs:comment "Header section includes document/message details." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :DOC_Segment .

:hasUNS rdf:type owl:ObjectProperty ;
  rdfs:label "has UNS segment" ;
  rdfs:comment "Summary section includes UNS segment for section control." ;
  rdfs:domain :SummarySection ;
  rdfs:range :UNS_Segment ;
  owl:FunctionalProperty .

:hasCNT rdf:type owl:ObjectProperty ;
  rdfs:label "has CNT segment" ;
  rdfs:comment "Summary section includes CNT segment for control totals." ;
