  rdfs:subClassOf :AgentRole .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address (headquarters, warehouse, etc.) for organizations." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "Identifier for organization locations." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice message." ;
  rdfs:subClassOf :Message .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." ;
  rdfs:subClassOf :Message .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals, taxes, and summary data." ;
  rdfs:subClassOf :Message .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A single invoice line, anchored by LIN_Segment." ;
  rdfs:subClassOf :DetailSection .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "Product or service sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price details for an item." .

:Quantity rdf:type owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "Quantity of item sold." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax applicable to the invoice or line item." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for invoice, PO, etc." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process context for the invoice." .

:InvoiceAmount rdf:type owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "Total amount for the invoice." .

:InvoiceNumber rdf:type owl:Class ;
  rdfs:label "Invoice Number" ;
  rdfs:comment "Unique identifier for the invoice." .

