#################################################################
# Advanced Axioms & Restrictions
#################################################################

:LineItem rdf:type owl:Class ;
  owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :hasLIN ; owl:allValuesFrom :LIN_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:allValuesFrom xsd:decimal ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom xsd:integer ] .

:OrganizationRoleAssignment rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ] .

:Invoice rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasOrganization ; owl:someValuesFrom :Organization ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasBusinessProcess ; owl:allValuesFrom :BusinessProcess ] .

:HeaderSection rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasDate ; owl:someValuesFrom :DTM_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasReferenceGroup ; owl:someValuesFrom :SG2_ReferenceGroup ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasHeaderTax ; owl:someValuesFrom :SG6_TaxGroup ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasHeaderAllowanceOrCharge ; owl:someValuesFrom :SG8_AllowanceChargeGroup ] .

:SummarySection rdf:type owl:Class ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasUNS ; owl:allValuesFrom :UNS_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasCNT ; owl:allValuesFrom :CNT_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasMonetaryAmount ; owl:someValuesFrom :MOA_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasTaxDetail ; owl:someValuesFrom :TAX_Segment ] ;
  rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasAllowanceOrCharge ; owl:someValuesFrom :ALC_Segment ] .

