  rdfs:subClassOf :Segment .

:TAX_Segment rdf:type owl:Class ;
  rdfs:label "Tax Segment (TAX)" ;
  rdfs:comment "Tax details, rates, and types." ;
  rdfs:subClassOf :Segment .

:MEA_Segment rdf:type owl:Class ;
  rdfs:label "Measurement Segment (MEA)" ;
  rdfs:comment "Measurements relevant to items or logistics." ;
