    rdfs:domain :DTMSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has date value" ;
    rdfs:comment "Date value in the DTM segment." .

:hasDate a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has date" ;
    rdfs:comment "Date associated with the document." .

