    rdfs:range :PaymentTermsSegment ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links an InvoiceMessage to its PaymentTerms segment." .
:paymentTermsOfInvoice a rdf:type owl:ObjectProperty ;
    rdfs:domain :PaymentTermsSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "payment terms of invoice" ;
    rdfs:comment "Inverse of hasPaymentTerms." ;
    owl:inverseOf :hasPaymentTerms .

:hasTaxSegment a rdf:type owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links an InvoiceMessage to its Tax segment for breakdowns." .
:taxSegmentOfInvoice a rdf:type owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "tax segment of invoice" ;
    rdfs:comment "Inverse of hasTaxSegment." ;
    owl:inverseOf :hasTaxSegment .

:hasAllowanceCharge a rdf:type owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an InvoiceMessage to Allowance/Charge segments." .
:allowanceChargeOfInvoice a rdf:type owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "allowance/charge of invoice" ;
    rdfs:comment "Inverse of hasAllowanceCharge." ;
    owl:inverseOf :hasAllowanceCharge .

:BGMSegment owl:disjointWith :NADSegment, :DTMSegment, :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:NADSegment owl:disjointWith :DTMSegment, :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:DTMSegment owl:disjointWith :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:PaymentTermsSegment owl:disjointWith :TaxSegment, :AllowanceChargeSegment .
:TaxSegment owl:disjointWith :AllowanceChargeSegment .

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:WarehouseAddress owl:disjointWith :HeadquartersAddress .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

:AgentRole owl:disjointUnionOf (:BuyerRole :DeliveryPartyRole) .
