:organizationHasAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "An organization has a role assignment in an invoice message." ;
    owl:inverseOf :forOrganization .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .
:addressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "An address is associated with an organization." ;
    owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number identifying the organization." .

:hasItem a owl:ObjectProperty ;
