    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "for organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization playing the role." .
:organizationHasAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "organization has assignment" ;
    rdfs:comment "Inverse of forOrganization." ;
    owl:inverseOf :forOrganization .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .
:addressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "address of organization" ;
    rdfs:comment "Inverse of hasAddress." ;
    owl:inverseOf :hasAddress .

