@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACTInvoiceOntology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A/EANCOM Invoice Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT D96A/EANCOM INVOIC messages, compliant with EN 16931-1 and P2P-O alignment." .

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "EDIFACT Message" ;
    rdfs:comment "A message within an interchange envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An invoice message (e.g., INVOIC) within the interchange." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "EDIFACT Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment. Mandatory for document and delivery dates." ;
    rdfs:subClassOf :Segment .

:PaymentTermsSegment a owl:Class ;
    rdfs:label "Payment Terms Segment" ;
    rdfs:comment "Segment describing payment terms." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Segment for tax breakdowns." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Segment for allowances and charges." ;
    rdfs:subClassOf :Segment .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section of the invoice message." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section containing line items." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section with totals and tax." ;
    rdfs:subClassOf :Segment .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address." .

:WarehouseAddress a owl:Class ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "A warehouse address for delivery." ;
    rdfs:subClassOf :Address .

:HeadquartersAddress a owl:Class ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "The main headquarters address of an organization." ;
    rdfs:subClassOf :Address .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GLN identifying an organization." ;
    rdfs:subClassOf :SimpleDataElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service being sold." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value for an item or invoice." ;
    rdfs:subClassOf :SimpleDataElement .

:NetPrice a owl:Class ;
    rdfs:label "Net Price" ;
    rdfs:comment "The net price of a line item." ;
    rdfs:subClassOf :Price .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total invoice amount." .

:DocumentReference a owl:Class ;
    rdfs:label "Document Reference" ;
    rdfs:comment "Reference to a document, such as an invoice number." .

:BusinessProcessAssignment a owl:Class ;
    rdfs:label "Business Process Assignment" ;
    rdfs:comment "Assignment of the invoice to a business process." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating document structure/content." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite." .

:EDIFACTDelimiter a owl:Class ;
    rdfs:label "EDIFACT Delimiter" ;
    rdfs:comment "A delimiter used in EDIFACT message syntax." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within a message context." .

:InvoiceLineItemAssignment a owl:Class ;
    rdfs:label "Invoice Line Item Assignment" ;
    rdfs:comment "Reifies assignment of line items to the invoice." .

:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to a contained Message." .
:containedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A message is contained in an interchange envelope." ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." .
:segmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "A segment is part of a message." ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an InvoiceMessage to its Header, Detail, and Summary sections." .
:sectionOfInvoice a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is section of invoice" ;
    rdfs:comment "A section is part of an invoice message." ;
    owl:inverseOf :hasSection .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a DetailSection to its LineItems." .
:lineItemOfSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of section" ;
    rdfs:comment "A line item is part of a detail section." ;
    owl:inverseOf :hasLineItem .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an InvoiceMessage to an involved Organization." .
:organizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in invoice message" ;
    rdfs:comment "An organization is involved in an invoice message." ;
    owl:inverseOf :involvesOrganization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an InvoiceMessage to OrganizationRoleAssignments (pivot class for reification of organization roles)." .
:roleAssignmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is role assignment of invoice" ;
    rdfs:comment "A role assignment is part of an invoice message." ;
    owl:inverseOf :hasRoleAssignment .

:hasRole a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
