    rdfs:comment "Date/Time/Period segment. Mandatory for document and delivery dates." ;
    rdfs:subClassOf :Segment .

:PaymentTermsSegment a owl:Class ;
    rdfs:label "Payment Terms Segment" ;
    rdfs:comment "Segment describing payment terms." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "Segment for tax breakdowns." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment" ;
    rdfs:comment "Segment for allowances and charges." ;
    rdfs:subClassOf :Segment .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section of the invoice message." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section containing line items." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section with totals and tax." ;
    rdfs:subClassOf :Segment .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address." .

:WarehouseAddress a owl:Class ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "A warehouse address for delivery." ;
    rdfs:subClassOf :Address .

:HeadquartersAddress a owl:Class ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "The main headquarters address of an organization." ;
    rdfs:subClassOf :Address .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GLN identifying an organization." ;
    rdfs:subClassOf :SimpleDataElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service being sold." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value for an item or invoice." ;
    rdfs:subClassOf :SimpleDataElement .

:NetPrice a owl:Class ;
    rdfs:label "Net Price" ;
    rdfs:comment "The net price of a line item." ;
    rdfs:subClassOf :Price .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total invoice amount." .

:DocumentReference a owl:Class ;
    rdfs:label "Document Reference" ;
    rdfs:comment "Reference to a document, such as an invoice number." .

:BusinessProcessAssignment a owl:Class ;
    rdfs:label "Business Process Assignment" ;
    rdfs:comment "Assignment of the invoice to a business process." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating document structure/content." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite." .

:EDIFACTDelimiter a owl:Class ;
    rdfs:label "EDIFACT Delimiter" ;
    rdfs:comment "A delimiter used in EDIFACT message syntax." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within a message context." .

:InvoiceLineItemAssignment a owl:Class ;
    rdfs:label "Invoice Line Item Assignment" ;
    rdfs:comment "Reifies assignment of line items to the invoice." .

:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to a contained Message." .
:containedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A message is contained in an interchange envelope." ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." .
:segmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "A segment is part of a message." ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    rdfs:label "has section" ;
    rdfs:comment "Links an InvoiceMessage to its Header, Detail, and Summary sections." .
:sectionOfInvoice a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is section of invoice" ;
    rdfs:comment "A section is part of an invoice message." ;
    owl:inverseOf :hasSection .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a DetailSection to its LineItems." .
:lineItemOfSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of section" ;
    rdfs:comment "A line item is part of a detail section." ;
    owl:inverseOf :hasLineItem .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an InvoiceMessage to an involved Organization." .
:organizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in invoice message" ;
    rdfs:comment "An organization is involved in an invoice message." ;
    owl:inverseOf :involvesOrganization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an InvoiceMessage to OrganizationRoleAssignments (pivot class for reification of organization roles)." .
:roleAssignmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is role assignment of invoice" ;
    rdfs:comment "A role assignment is part of an invoice message." ;
    owl:inverseOf :hasRoleAssignment .

:hasRole a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Links an OrganizationRoleAssignment to an AgentRole." .
:roleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "An agent role is assigned to an organization role assignment." ;
    owl:inverseOf :hasRole .

:forOrganization a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "for organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization playing the role." .
:organizationHasAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "An organization has a role assignment in an invoice message." ;
    owl:inverseOf :forOrganization .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .
:addressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "An address is associated with an organization." ;
    owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number identifying the organization." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links a LineItem to the sold Item." .
:itemOfLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is item of line item" ;
    rdfs:comment "An item is part of a line item." ;
    owl:inverseOf :hasItem .

:hasNetPrice a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :NetPrice ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a LineItem to its net price." .
:netPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :NetPrice ;
    rdfs:range :LineItem ;
    rdfs:label "is net price of line item" ;
    rdfs:comment "A net price is associated with a line item." ;
    owl:inverseOf :hasNetPrice .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of items in a LineItem." .

:hasInvoiceAmount a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links the SummarySection to the total invoice amount." .
:invoiceAmountOfSummary a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is invoice amount of summary" ;
    rdfs:comment "An invoice amount is part of a summary section." ;
    owl:inverseOf :hasInvoiceAmount .

:hasTaxAmount a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :TaxAmount ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Links the SummarySection to the total tax amount." .
:taxAmountOfSummary a owl:ObjectProperty ;
    rdfs:domain :TaxAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax amount of summary" ;
    rdfs:comment "A tax amount is part of a summary section." ;
    owl:inverseOf :hasTaxAmount .

:hasDocumentReference a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :DocumentReference ;
    rdfs:label "has document reference" ;
    rdfs:comment "Links the HeaderSection to document references such as invoice number." .
:documentReferenceOfHeader a owl:ObjectProperty ;
    rdfs:domain :DocumentReference ;
    rdfs:range :HeaderSection ;
    rdfs:label "is document reference of header" ;
    rdfs:comment "A document reference is part of a header section." ;
    owl:inverseOf :hasDocumentReference .

:hasReferenceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :DocumentReference ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "Reference number for a document (e.g., invoice number)." .

:hasDateQualifier a owl:DatatypeProperty ;
    rdfs:domain :DTMSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has date qualifier" ;
    rdfs:comment "Qualifier indicating the type of date (e.g., document date, delivery date)." .

:hasDateValue a owl:DatatypeProperty ;
    rdfs:domain :DTMSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has date value" ;
    rdfs:comment "Date value in the DTM segment." .

:hasDate a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has date" ;
    rdfs:comment "Date associated with the document." .

:isAssignedTo a owl:ObjectProperty ;
    rdfs:domain :InvoiceLineItemAssignment ;
    rdfs:range :LineItem ;
    rdfs:label "is assigned to" ;
    rdfs:comment "Links a pivot assignment to a LineItem." .
:assignmentOfLineItem a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceLineItemAssignment ;
    rdfs:label "is assignment of line item" ;
    rdfs:comment "A line item is linked to its assignment." ;
    owl:inverseOf :isAssignedTo .

:hasBusinessProcessAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcessAssignment ;
    rdfs:label "has business process assignment" ;
    rdfs:comment "Links an InvoiceMessage to a BusinessProcessAssignment." .
:businessProcessAssignmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :BusinessProcessAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process assignment of invoice" ;
    rdfs:comment "A business process assignment is associated with an invoice message." ;
    owl:inverseOf :hasBusinessProcessAssignment .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Links an InvoiceMessage to a ValidationConstraint (for SHACL-style validation knowledge)." .
:validationConstraintOfInvoice a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validation constraint of invoice" ;
    rdfs:comment "A validation constraint is associated with an invoice message." ;
    owl:inverseOf :hasValidationConstraint .

:hasCompositeDataElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite data element" ;
    rdfs:comment "Links a Segment to its CompositeDataElements." .
:compositeDataElementOfSegment a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite data element of segment" ;
    rdfs:comment "A composite data element is part of a segment." ;
    owl:inverseOf :hasCompositeDataElement .

:hasSimpleDataElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple data element" ;
    rdfs:comment "Links a CompositeDataElement to its SimpleDataElements." .
:simpleDataElementOfComposite a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple data element of composite" ;
    rdfs:comment "A simple data element is part of a composite data element." ;
    owl:inverseOf :hasSimpleDataElement .

:hasDelimiter a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :EDIFACTDelimiter ;
    rdfs:label "has delimiter" ;
    rdfs:comment "Links an InterchangeEnvelope to its delimiter definitions." .
:delimiterOfEnvelope a owl:ObjectProperty ;
    rdfs:domain :EDIFACTDelimiter ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is delimiter of envelope" ;
    rdfs:comment "A delimiter is associated with an interchange envelope." ;
    owl:inverseOf :hasDelimiter .

:hasPaymentTerms a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :PaymentTermsSegment ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links an InvoiceMessage to its PaymentTerms segment." .
:paymentTermsOfInvoice a owl:ObjectProperty ;
    rdfs:domain :PaymentTermsSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is payment terms of invoice" ;
    rdfs:comment "Payment terms are associated with an invoice message." ;
    owl:inverseOf :hasPaymentTerms .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links an InvoiceMessage to its Tax segment for breakdowns." .
:taxSegmentOfInvoice a owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is tax segment of invoice" ;
    rdfs:comment "A tax segment is associated with an invoice message." ;
    owl:inverseOf :hasTaxSegment .

:hasAllowanceCharge a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance/charge" ;
    rdfs:comment "Links an InvoiceMessage to Allowance/Charge segments." .
:allowanceChargeOfInvoice a owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is allowance/charge of invoice" ;
    rdfs:comment "An allowance/charge segment is associated with an invoice message." ;
    owl:inverseOf :hasAllowanceCharge .

:BGMSegment owl:disjointWith :NADSegment, :DTMSegment, :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:NADSegment owl:disjointWith :DTMSegment, :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:DTMSegment owl:disjointWith :PaymentTermsSegment, :TaxSegment, :AllowanceChargeSegment .
:PaymentTermsSegment owl:disjointWith :TaxSegment, :AllowanceChargeSegment .
:TaxSegment owl:disjointWith :AllowanceChargeSegment .

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:WarehouseAddress owl:disjointWith :HeadquartersAddress .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

:AgentRole owl:disjointUnionOf (:BuyerRole :DeliveryPartyRole) .

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACTInvoiceOntology> a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT invoice messages, segments, and roles as per D96A and EN 16931-1, aligned with P2P-O and supporting SHACL validation." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as an invoice." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT INVOIC message representing an invoice." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a segment." .

:Section a owl:Class ;
    rdfs:label "Section" ;
    rdfs:comment "A logical section of the invoice (header, detail, summary)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document dates and references." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section listing individual line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section providing totals such as tax and invoice amount." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "The role an organization plays in the invoice (e.g., Buyer, Seller, Delivery Party)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "Reification class linking an organization to a role for a given invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations, items, etc." .

:GlobalLocationNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organizations as per D96A." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price amount." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity of items." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "The business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for automated validation, e.g., SHACL shapes." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to its contained Messages." ;
    owl:FunctionalProperty .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Section ;
    rdfs:label "has section" ;
    rdfs:comment "Links an InvoiceMessage to its header, detail, or summary section." ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite element to its simple elements." .

:representsOrganization a owl:ObjectProperty ;
    rdfs:domain :NAD_Segment ;
    rdfs:range :Organization ;
    rdfs:label "represents organization" ;
    rdfs:comment "Links a NAD segment to an organization." .

:hasRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Specifies the role in a RoleAssignment." ;
    owl:FunctionalProperty .

:assignedTo a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned to" ;
    rdfs:comment "Specifies the organization in a RoleAssignment." ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:FunctionalProperty .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifiers." .

:hasGlobalLocationNumber a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has global location number" ;
    rdfs:comment "Links an organization to its GLN identifier." ;
    owl:FunctionalProperty .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "plays role" ;
    rdfs:comment "Links an organization to its role assignments." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links the detail section to items sold." .

:itemPrice a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :Price ;
    rdfs:label "item price" ;
    rdfs:comment "Links an item to its price." ;
    owl:FunctionalProperty .

:itemQuantity a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :Quantity ;
    rdfs:label "item quantity" ;
    rdfs:comment "Links an item to its quantity." ;
    owl:FunctionalProperty .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax information." .

:invoiceAmount a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Price ;
